export function withFritzingGeometry(def: PartDef): PartDef {
	const g = FRITZING_GEOMETRY[def.type];
	if (!g) return def;
	return {
		...def,
		width: g.width,
		height: g.height,
		pins: def.pins.map((pin) => {
			const at = g.pins[pin.name];
			return at ? { ...pin, x: at.x, y: at.y } : pin;
		})
	};
}
